DROP POLICY pedidos_equipe ON pedidos;
CREATE POLICY pedidos_equipe_sel ON pedidos AS PERMISSIVE FOR SELECT TO atendente, gerente USING (true);
CREATE POLICY pedidos_atendente_ins ON pedidos AS PERMISSIVE FOR INSERT TO atendente WITH CHECK (true);

-- Opcao: tabela de mapeamento login->cliente, que a sessao nao consegue alterar
CREATE TABLE cliente_login (login name PRIMARY KEY, cliente_id integer NOT NULL);
ALTER TABLE cliente_login OWNER TO admin_bd;
REVOKE ALL ON cliente_login FROM PUBLIC;
CREATE FUNCTION cliente_atual() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT cliente_id FROM cliente_login WHERE login = session_user $$;
REVOKE ALL ON FUNCTION cliente_atual() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION cliente_atual() TO cliente;
ALTER POLICY pedidos_cliente_sel ON pedidos USING (cliente_id = cliente_atual());
ALTER POLICY pedidos_cliente_ins ON pedidos WITH CHECK (cliente_id = cliente_atual());
ALTER POLICY clientes_cliente_sel ON clientes USING (id = cliente_atual());
